@Composable
fun EditItemDialog(
    item: InventoryItem,
    onConfirm: (InventoryItem) -> Unit,
    onCancel: () -> Unit
) {
    // maintain state for editable fields
    val name = item.name
    var stock by remember { mutableStateOf(item.stock.toString()) }
    var price by remember { mutableStateOf(item.price.toString()) } // Add a state variable for price

    AlertDialog(
        onDismissRequest = onCancel,
        title = { Text(text = "Edit Item") },
        text = {
            Column {
                TextField(
                    value = stock,
                    onValueChange = { newText ->
                        stock = newText
                    },
                    // ...Rest of the TextField configuration
                )
                TextField(
                    value = price,
                    onValueChange = { newText ->
                        price = newText
                    },
                    supportingText = { Text("Price") },
                    keyboardOptions = KeyboardOptions(
                        keyboardType = KeyboardType.Number,
                        imeAction = ImeAction.Done
                    ),
                    keyboardActions = KeyboardActions(onDone = { })
                )
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    val updatedItem = item.copy(
                        name = name,
                        stock = stock.toInt(),
                        price = price.toDouble() // Add the updated price in the item
                    )
                    onConfirm(updatedItem)
                }
            ) {
                Text("Confirm")
            }
        },
        dismissButton = {
            Button(onClick = onCancel) {
                Text("Cancel")
            }
        }
    )
}
```

Please note that the TextField for the price field now has an initial value set to `price`. Also, when creating the updatedItem, the item is now copied with the updated `price` by converting it to a `Double`.
